package httpapi

import (
	"errors"
	"net/http"

	"notes/internal/store"
)

// handleUpdate implements PUT /notes/{id}: full replacement of a note.
// An omitted body or tags field resets it to "" or [].
func (s *Server) handleUpdate(w http.ResponseWriter, r *http.Request) {
	id, ok := s.noteID(w, r)
	if !ok {
		return
	}
	in, ok := s.readInput(w, r)
	if !ok {
		return
	}
	n, err := s.store.Update(r.Context(), id, in)
	if errors.Is(err, store.ErrNotFound) {
		s.notFound(w)
		return
	}
	if err != nil {
		s.serverError(w, r, err)
		return
	}
	s.writeJSON(w, http.StatusOK, n)
}

// handleDelete implements DELETE /notes/{id}.
func (s *Server) handleDelete(w http.ResponseWriter, r *http.Request) {
	id, ok := s.noteID(w, r)
	if !ok {
		return
	}
	err := s.store.Delete(r.Context(), id)
	if errors.Is(err, store.ErrNotFound) {
		s.notFound(w)
		return
	}
	if err != nil {
		s.serverError(w, r, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

package httpapi

import (
	"net/http"
	"testing"
)

func TestUpdateNote(t *testing.T) {
	url := newTestServer(t)
	if status, body := do(t, http.MethodPost, url+"/notes", `{"title":"old","body":"text","tags":["x"]}`); status != http.StatusCreated {
		t.Fatalf("POST = %d %s", status, body)
	}

	status, body := do(t, http.MethodPut, url+"/notes/1", `{"title":"  new ","tags":["b","a","b"]}`)
	if status != http.StatusOK {
		t.Fatalf("PUT = %d %s, want 200", status, body)
	}
	want := `{"id":1,"title":"new","body":"","tags":["a","b"]}`
	assertJSON(t, body, want)
	_, body = do(t, http.MethodGet, url+"/notes/1", "")
	assertJSON(t, body, want)

	tests := []struct {
		name, path, body string
		status           int
	}{
		{"missing note", "/notes/9", `{"title":"none"}`, http.StatusNotFound},
		{"invalid id", "/notes/abc", `{"title":"x"}`, http.StatusNotFound},
		{"zero id", "/notes/0", `{"title":"x"}`, http.StatusNotFound},
		{"empty title", "/notes/1", `{"title":""}`, http.StatusBadRequest},
		{"missing title", "/notes/1", `{"body":"b"}`, http.StatusBadRequest},
		{"not an object", "/notes/1", `["title"]`, http.StatusBadRequest},
		{"invalid JSON", "/notes/1", `{"title":`, http.StatusBadRequest},
		{"body not a string", "/notes/1", `{"title":"x","body":1}`, http.StatusBadRequest},
		{"invalid tag", "/notes/1", `{"title":"x","tags":["A"]}`, http.StatusBadRequest},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			status, body := do(t, http.MethodPut, url+tt.path, tt.body)
			if status != tt.status {
				t.Fatalf("PUT %s %s = %d, want %d", tt.path, tt.body, status, tt.status)
			}
			assertError(t, body)
		})
	}

	// Failed updates leave the note unchanged.
	_, body = do(t, http.MethodGet, url+"/notes/1", "")
	assertJSON(t, body, want)
}

func TestDeleteNote(t *testing.T) {
	url := newTestServer(t)
	for _, title := range []string{"a", "b"} {
		if status, body := do(t, http.MethodPost, url+"/notes", `{"title":"`+title+`"}`); status != http.StatusCreated {
			t.Fatalf("POST = %d %s", status, body)
		}
	}

	status, body := do(t, http.MethodDelete, url+"/notes/1", "")
	if status != http.StatusNoContent || body != "" {
		t.Fatalf("DELETE = %d %q, want 204 with empty body", status, body)
	}
	for _, req := range [][2]string{
		{http.MethodGet, "/notes/1"},
		{http.MethodDelete, "/notes/1"},
		{http.MethodPut, "/notes/1"},
		{http.MethodDelete, "/notes/abc"},
		{http.MethodDelete, "/notes/-2"},
	} {
		status, body := do(t, req[0], url+req[1], `{"title":"x"}`)
		if status != http.StatusNotFound {
			t.Errorf("%s %s = %d, want 404", req[0], req[1], status)
			continue
		}
		assertError(t, body)
	}

	status, body = do(t, http.MethodPost, url+"/notes", `{"title":"c"}`)
	if status != http.StatusCreated {
		t.Fatalf("POST = %d %s", status, body)
	}
	assertJSON(t, body, `{"id":3,"title":"c","body":"","tags":[]}`)
}

package httpapi

import (
	"context"
	"encoding/json"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"testing"

	"notes/internal/store"
)

// newTestServer starts the API on a fresh database and returns its base URL.
func newTestServer(t *testing.T) string {
	t.Helper()
	st, err := store.Open(context.Background(), filepath.Join(t.TempDir(), "notes.db"))
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	ts := httptest.NewServer(New(st, slog.New(slog.DiscardHandler)))
	t.Cleanup(func() {
		ts.Close()
		st.Close()
	})
	return ts.URL
}

// do sends a request with an optional body and returns the status and body.
func do(t *testing.T, method, url, body string) (int, string) {
	t.Helper()
	var r io.Reader
	if body != "" {
		r = strings.NewReader(body)
	}
	req, err := http.NewRequest(method, url, r)
	if err != nil {
		t.Fatal(err)
	}
	if body != "" {
		req.Header.Set("Content-Type", "application/json")
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	data, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatal(err)
	}
	return resp.StatusCode, string(data)
}

// assertJSON fails unless got and want are equal JSON documents.
func assertJSON(t *testing.T, got, want string) {
	t.Helper()
	var g, w any
	if err := json.Unmarshal([]byte(got), &g); err != nil {
		t.Fatalf("response is not JSON: %q", got)
	}
	if err := json.Unmarshal([]byte(want), &w); err != nil {
		t.Fatalf("bad expectation %q: %v", want, err)
	}
	gb, _ := json.Marshal(g)
	wb, _ := json.Marshal(w)
	if string(gb) != string(wb) {
		t.Errorf("body = %s, want %s", gb, wb)
	}
}

// assertError fails unless body is a JSON {"error": "..."} object.
func assertError(t *testing.T, body string) {
	t.Helper()
	var e errorBody
	if err := json.Unmarshal([]byte(body), &e); err != nil || e.Error == "" {
		t.Errorf("body %q is not a JSON error", body)
	}
}

package httpapi

import (
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"strconv"

	"notes/internal/note"
	"notes/internal/store"
)

type listResponse struct {
	Notes []note.Note `json:"notes"`
}

// handleList implements GET /notes with the tag, q, after and limit query parameters.
func (s *Server) handleList(w http.ResponseWriter, r *http.Request) {
	f, err := parseListFilter(r.URL.Query())
	if err != nil {
		s.writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	notes, err := s.store.List(r.Context(), f)
	if err != nil {
		s.serverError(w, r, err)
		return
	}
	s.writeJSON(w, http.StatusOK, listResponse{Notes: notes})
}

// parseListFilter builds a store.ListFilter from the query parameters of
// GET /notes. When a parameter is repeated, the first value wins.
func parseListFilter(q url.Values) (store.ListFilter, error) {
	f := store.ListFilter{Limit: store.MaxListLimit}

	if q.Has("tag") {
		tag := q.Get("tag")
		f.Tag = &tag
	}
	f.Query = q.Get("q")

	if q.Has("after") {
		after, err := strconv.ParseInt(q.Get("after"), 10, 64)
		// An out-of-range integer is still an integer: ParseInt clamps it to
		// the nearest int64, which selects the same notes.
		if err != nil && !errors.Is(err, strconv.ErrRange) {
			return store.ListFilter{}, errors.New("after must be an integer")
		}
		f.After = after
	}

	if q.Has("limit") {
		limit, err := strconv.Atoi(q.Get("limit"))
		if err != nil || limit < 1 || limit > store.MaxListLimit {
			return store.ListFilter{}, fmt.Errorf("limit must be an integer from 1 to %d", store.MaxListLimit)
		}
		f.Limit = limit
	}

	return f, nil
}

