		assertError(t, body)
	}
}

package httpapi

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"

	"notes/internal/note"
)

// maxBodyBytes bounds request bodies. The specification sets no limit on the
// size of a note body, so this is generous; it only guards against abuse.
const maxBodyBytes = 16 << 20

type errorBody struct {
	Error string `json:"error"`
}

// writeJSON sends v as a JSON response with the given status.
func (s *Server) writeJSON(w http.ResponseWriter, status int, v any) {
	data, err := json.Marshal(v)
	if err != nil {
		s.log.Error("encode response", "err", err)
		w.WriteHeader(http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write(append(data, '\n'))
}

// writeError sends {"error": msg} with the given status.
func (s *Server) writeError(w http.ResponseWriter, status int, msg string) {
	s.writeJSON(w, status, errorBody{Error: msg})
}

// serverError logs err and sends a generic 500 response.
func (s *Server) serverError(w http.ResponseWriter, r *http.Request, err error) {
	s.log.Error("request failed", "method", r.Method, "path", r.URL.Path, "err", err)
	s.writeError(w, http.StatusInternalServerError, "internal server error")
}

// notFound sends a 404 response.
func (s *Server) notFound(w http.ResponseWriter) {
	s.writeError(w, http.StatusNotFound, "note not found")
}

// noteID parses the {id} path value as a positive decimal integer. On failure
// it writes a 404 response (an invalid id names no note) and returns false.
func (s *Server) noteID(w http.ResponseWriter, r *http.Request) (int64, bool) {
	raw := r.PathValue("id")
	for i := 0; i < len(raw); i++ {
		if raw[i] < '0' || raw[i] > '9' {
			s.notFound(w)
			return 0, false
		}
	}
	id, err := strconv.ParseInt(raw, 10, 64)
	if err != nil || id <= 0 {
		s.notFound(w)
		return 0, false
	}
	return id, true
}

// readInput reads and validates a {title, body?, tags?} request body. On
// failure it writes a 4xx response and returns false.
func (s *Server) readInput(w http.ResponseWriter, r *http.Request) (note.Input, bool) {
	data, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
	if err != nil {
		if maxErr := (*http.MaxBytesError)(nil); errors.As(err, &maxErr) {
			s.writeError(w, http.StatusRequestEntityTooLarge, "request body too large")
		} else {
			s.writeError(w, http.StatusBadRequest, "could not read request body")
		}
		return note.Input{}, false
	}
	in, err := note.ParseInput(data)
	if err != nil {
		s.writeError(w, http.StatusBadRequest, err.Error())
		return note.Input{}, false
	}
	return in, true
}

// Package httpapi exposes the notes store over HTTP.
//
// Files are split by feature so they can be developed independently:
//
//	server.go   Server, routing table and error rewriting for unmatched routes
//	respond.go  shared request/response helpers
//	notes.go    POST /notes, GET /notes/{id}
//	crud.go     PUT /notes/{id}, DELETE /notes/{id}
//	list.go     GET /notes
//	stats.go    GET /stats, GET /tags
package httpapi

import (
	"encoding/json"
	"log/slog"
	"net/http"
	"strings"

	"notes/internal/store"
)

// Server routes HTTP requests to the notes store. It is safe for concurrent use.
type Server struct {
	store *store.Store
	log   *slog.Logger
	mux   *http.ServeMux
}

// New returns a Server backed by st that logs unexpected errors to log.
func New(st *store.Store, log *slog.Logger) *Server {
	s := &Server{store: st, log: log, mux: http.NewServeMux()}
	s.routes()
	return s
}

// routes is the complete routing table. Handlers live in their feature files.
// A path registered for some methods automatically answers 405 for the others.
func (s *Server) routes() {
	s.mux.HandleFunc("GET /health", s.handleHealth)

	s.mux.HandleFunc("POST /notes", s.handleCreate)
	s.mux.HandleFunc("GET /notes/{id}", s.handleGet)

	s.mux.HandleFunc("PUT /notes/{id}", s.handleUpdate)
	s.mux.HandleFunc("DELETE /notes/{id}", s.handleDelete)

	s.mux.HandleFunc("GET /notes", s.handleList)

	s.mux.HandleFunc("GET /stats", s.handleStats)
	s.mux.HandleFunc("GET /tags", s.handleTags)
}

// ServeHTTP implements http.Handler.
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if _, pattern := s.mux.Handler(r); pattern == "" {
		// No route matched: the mux answers 404, 405 or a redirect in plain
		// text. Keep its status and headers (such as Allow) but send the
		// error body as JSON like every other error.
		w = &jsonErrorWriter{ResponseWriter: w}
	}
	s.mux.ServeHTTP(w, r)
}

func (s *Server) handleHealth(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	_, _ = w.Write([]byte("ok"))
}

// jsonErrorWriter replaces the body of error responses with {"error": "..."}.
type jsonErrorWriter struct {
	http.ResponseWriter
	discard bool
}

func (w *jsonErrorWriter) WriteHeader(code int) {
	if code < http.StatusBadRequest {
		w.ResponseWriter.WriteHeader(code)
		return
	}
	w.discard = true
	w.Header().Set("Content-Type", "application/json")
	w.ResponseWriter.WriteHeader(code)
	_ = json.NewEncoder(w.ResponseWriter).Encode(errorBody{Error: strings.ToLower(http.StatusText(code))})
}

func (w *jsonErrorWriter) Write(b []byte) (int, error) {
	if w.discard {
		return len(b), nil
	}
	return w.ResponseWriter.Write(b)
}

package httpapi

import "net/http"

type statsResponse struct {
	Notes int64            `json:"notes"`
	Tags  map[string]int64 `json:"tags"`
}

// tagCount has the fields of store.TagCount, so one converts to the other.
type tagCount struct {
	Tag   string `json:"tag"`
	Count int64  `json:"count"`
}

type tagsResponse struct {
	Tags []tagCount `json:"tags"`
}

// handleStats implements GET /stats.
func (s *Server) handleStats(w http.ResponseWriter, r *http.Request) {
	st, err := s.store.Stats(r.Context())
	if err != nil {
		s.serverError(w, r, err)
		return
	}
	s.writeJSON(w, http.StatusOK, statsResponse{Notes: st.Notes, Tags: st.Tags})
}

// handleTags implements GET /tags.
func (s *Server) handleTags(w http.ResponseWriter, r *http.Request) {
	counts, err := s.store.TagCounts(r.Context())
	if err != nil {
		s.serverError(w, r, err)
		return
	}
	resp := tagsResponse{Tags: make([]tagCount, len(counts))}
	for i, tc := range counts {
		resp.Tags[i] = tagCount(tc)
	}
	s.writeJSON(w, http.StatusOK, resp)
}

