	if counts == nil || len(counts) != 0 {
		t.Errorf("TagCounts = %#v, want an empty non-nil slice", counts)
	}
}

func TestStatsAndTagCounts(t *testing.T) {
	s, _ := openTestStore(t)
	ctx := context.Background()

	mustCreate(t, s, note.Input{Title: "a", Tags: []string{"b", "z"}})
	mustCreate(t, s, note.Input{Title: "b", Tags: []string{"a", "z"}})
	mustCreate(t, s, note.Input{Title: "c", Tags: []string{"c", "z"}})
	mustCreate(t, s, note.Input{Title: "d", Tags: []string{"b"}})
	mustCreate(t, s, note.Input{Title: "e"})
	// Deleting a note removes its tags from the counts.
	gone := mustCreate(t, s, note.Input{Title: "f", Tags: []string{"a", "gone"}})
	if _, err := s.db.ExecContext(ctx, `DELETE FROM notes WHERE id = ?`, gone.ID); err != nil {
		t.Fatalf("delete: %v", err)
	}

	st, err := s.Stats(ctx)
	if err != nil {
		t.Fatalf("Stats: %v", err)
	}
	want := Stats{Notes: 5, Tags: map[string]int64{"a": 1, "b": 2, "c": 1, "z": 3}}
	if !reflect.DeepEqual(st, want) {
		t.Errorf("Stats = %#v, want %#v", st, want)
	}

	counts, err := s.TagCounts(ctx)
	if err != nil {
		t.Fatalf("TagCounts: %v", err)
	}
	wantCounts := []TagCount{{"z", 3}, {"b", 2}, {"a", 1}, {"c", 1}}
	if !reflect.DeepEqual(counts, wantCounts) {
		t.Errorf("TagCounts = %#v, want %#v", counts, wantCounts)
	}
}

// Package store persists notes in a SQLite database.
//
// The store is split by feature: this file holds the connection, the schema and
// the shared helpers; each group of operations lives in its own file.
package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"net/url"

	_ "modernc.org/sqlite" // registers the "sqlite" database/sql driver

	"notes/internal/note"
)

// ErrNotFound is returned when the requested note does not exist.
var ErrNotFound = errors.New("note not found")

// schema is idempotent so it can run on every start.
//
// AUTOINCREMENT guarantees that ids are never reused, even after the note with
// the highest id is deleted. Tags live in their own table so they can be
// filtered and counted with indexes; ON DELETE CASCADE drops them with the note.
const schema = `
CREATE TABLE IF NOT EXISTS notes (
	id    INTEGER PRIMARY KEY AUTOINCREMENT,
	title TEXT NOT NULL,
	body  TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS note_tags (
	note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
	tag     TEXT    NOT NULL,
	PRIMARY KEY (note_id, tag)
) WITHOUT ROWID;

CREATE INDEX IF NOT EXISTS note_tags_by_tag ON note_tags (tag, note_id);
`

// Store is safe for concurrent use.
type Store struct {
	db *sql.DB
}

// Open opens (creating if needed) the SQLite database at path and applies the schema.
func Open(ctx context.Context, path string) (*Store, error) {
	// Per-connection settings, applied in order: busy_timeout comes first so
	// that the pragmas after it already wait for locks held by other
	// connections instead of failing with SQLITE_BUSY. WAL lets readers run
	// alongside a writer, and _txlock=immediate takes the write lock at BEGIN
	// so that transactions never fail on a read-to-write lock upgrade.
	q := url.Values{}
	q.Add("_pragma", "busy_timeout(10000)")
	q.Add("_pragma", "foreign_keys(1)")
	q.Add("_pragma", "journal_mode(WAL)")
	q.Add("_pragma", "synchronous(NORMAL)")
	q.Set("_txlock", "immediate")
	dsn := "file:" + path + "?" + q.Encode()

	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open database: %w", err)
	}
	if _, err := db.ExecContext(ctx, schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Close releases the database.
func (s *Store) Close() error {
	return s.db.Close()
}

// selectNotes selects the columns read by scanNote. Tags are aggregated in the
// same statement so that a note and its tags come from one consistent snapshot.
// Append WHERE / ORDER BY / LIMIT clauses using the alias n for notes.
const selectNotes = `
SELECT n.id, n.title, n.body,
       (SELECT json_group_array(t.tag ORDER BY t.tag) FROM note_tags t WHERE t.note_id = n.id)
FROM notes n`

// scanner is implemented by *sql.Row and *sql.Rows.
type scanner interface {
	Scan(dest ...any) error
}

// scanNote reads one row produced by selectNotes.
func scanNote(row scanner) (note.Note, error) {
	var (
		n    note.Note
		tags string
	)
	if err := row.Scan(&n.ID, &n.Title, &n.Body, &tags); err != nil {
		return note.Note{}, err
	}
	if err := json.Unmarshal([]byte(tags), &n.Tags); err != nil {
		return note.Note{}, fmt.Errorf("decode tags of note %d: %w", n.ID, err)
	}
	if n.Tags == nil {
		n.Tags = []string{}
	}
	return n, nil
}

// inTx runs fn in a write transaction, committing if fn returns nil.
func (s *Store) inTx(ctx context.Context, fn func(tx *sql.Tx) error) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin transaction: %w", err)
	}
	defer tx.Rollback() //nolint:errcheck // no-op after Commit

	if err := fn(tx); err != nil {
		return err
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit: %w", err)
	}
	return nil
}

// insertTags stores tags for the note id. tags must already be normalized.
func insertTags(ctx context.Context, tx *sql.Tx, id int64, tags []string) error {
	if len(tags) == 0 {
		return nil
	}
	stmt, err := tx.PrepareContext(ctx, `INSERT INTO note_tags (note_id, tag) VALUES (?, ?)`)
	if err != nil {
		return fmt.Errorf("prepare tag insert: %w", err)
	}
	defer stmt.Close()
	for _, tag := range tags {
		if _, err := stmt.ExecContext(ctx, id, tag); err != nil {
			return fmt.Errorf("insert tag %q: %w", tag, err)
		}
	}
	return nil
}

package store

import (
	"context"
	"errors"
	"path/filepath"
	"reflect"
	"sync"
	"testing"

	"notes/internal/note"
)

// openTestStore opens a store on a fresh database file removed after the test.
func openTestStore(t *testing.T) (*Store, string) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "notes.db")
	s, err := Open(context.Background(), path)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	t.Cleanup(func() { s.Close() })
	return s, path
}

func mustCreate(t *testing.T, s *Store, in note.Input) note.Note {
	t.Helper()
	if in.Tags == nil {
		in.Tags = []string{}
	}
	n, err := s.Create(context.Background(), in)
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	return n
}

func TestCreateGet(t *testing.T) {
	s, _ := openTestStore(t)
	ctx := context.Background()

	a := mustCreate(t, s, note.Input{Title: "a"})
	b := mustCreate(t, s, note.Input{Title: "b", Body: "text", Tags: []string{"x", "y"}})
	if a.ID != 1 || b.ID != 2 {
		t.Fatalf("ids = %d, %d; want 1, 2", a.ID, b.ID)
	}

	for _, want := range []note.Note{
		{ID: 1, Title: "a", Body: "", Tags: []string{}},
		{ID: 2, Title: "b", Body: "text", Tags: []string{"x", "y"}},
	} {
		got, err := s.Get(ctx, want.ID)
		if err != nil {
			t.Fatalf("Get(%d): %v", want.ID, err)
		}
		if !reflect.DeepEqual(got, want) {
			t.Errorf("Get(%d) = %#v, want %#v", want.ID, got, want)
		}
	}

	if _, err := s.Get(ctx, 3); !errors.Is(err, ErrNotFound) {
		t.Errorf("Get(3) error = %v, want ErrNotFound", err)
	}
}

func TestPersistsAcrossReopen(t *testing.T) {
	s, path := openTestStore(t)
	mustCreate(t, s, note.Input{Title: "kept", Tags: []string{"t"}})
	s.Close()

	s2, err := Open(context.Background(), path)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer s2.Close()
	got, err := s2.Get(context.Background(), 1)
	if err != nil {
		t.Fatalf("Get after reopen: %v", err)
	}
	if got.Title != "kept" || !reflect.DeepEqual(got.Tags, []string{"t"}) {
		t.Errorf("after reopen got %#v", got)
	}
	if n := mustCreate(t, s2, note.Input{Title: "next"}); n.ID != 2 {
		t.Errorf("id after reopen = %d, want 2", n.ID)
	}
}

func TestConcurrentCreate(t *testing.T) {
	s, _ := openTestStore(t)
	const workers, perWorker = 8, 25

	var wg sync.WaitGroup
	errs := make(chan error, workers*perWorker)
	for range workers {
		wg.Go(func() {
			for range perWorker {
				if _, err := s.Create(context.Background(), note.Input{Title: "c", Tags: []string{"t"}}); err != nil {
					errs <- err
				}
			}
		})
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		t.Fatalf("concurrent Create: %v", err)
	}

	if _, err := s.Get(context.Background(), workers*perWorker); err != nil {
		t.Fatalf("Get last note: %v", err)
	}
}

// Command app serves the notes HTTP API: ./app <port>, with the SQLite
// database path in the NOTES_DB environment variable.
package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"notes/internal/httpapi"
	"notes/internal/store"
)

func main() {
	log := slog.New(slog.NewTextHandler(os.Stderr, nil))
	if err := run(log, os.Args[1:]); err != nil {
		log.Error("fatal", "err", err)
		os.Exit(1)
	}
}

func run(log *slog.Logger, args []string) error {
	if len(args) != 1 {
		return errors.New("usage: app <port>")
	}
	port, err := strconv.ParseUint(args[0], 10, 16)
	if err != nil || port == 0 {
		return fmt.Errorf("invalid port %q", args[0])
	}
	dbPath := os.Getenv("NOTES_DB")
	if dbPath == "" {
		return errors.New("NOTES_DB is not set")
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	st, err := store.Open(ctx, dbPath)
	if err != nil {
		return err
	}
	defer st.Close()

	ln, err := net.Listen("tcp", net.JoinHostPort("127.0.0.1", strconv.FormatUint(port, 10)))
	if err != nil {
		return err
	}

	srv := &http.Server{
		Handler:           httpapi.New(st, log),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       30 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       2 * time.Minute,
	}

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()
	log.Info("listening", "addr", ln.Addr().String(), "db", dbPath)

	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	return srv.Shutdown(shutdownCtx)
}
